      const pairs = new Map<number, number[]>();
      board.deck.forEach((face, index) => pairs.set(face, [...(pairs.get(face) ?? []), index]));
      for (let turn = 0; turn < 2; turn++) {
        await expect(page.locator('.tournament-owner')).toHaveText(`Now playing: ${names[players[turn] ?? 0]}`);
        await page.getByRole('button', { name: 'Start turn', exact: true }).click();
        await expect(page.locator('.card')).toHaveCount(board.deck.length);
        expect((await exported(page)).document.game?.boardCode).toBe(code);
        for (const pair of pairs.values()) for (const index of pair) await page.locator('.card').nth(index).click();
        await expect(page.getByRole('status')).toHaveCount(1);
        if (turn === 0) await page.getByRole('button', { name: 'Next turn', exact: true }).click();
      }
      if (match < count - 2) await page.getByRole('button', { name: 'Next match', exact: true }).click();
    }
