    await page.getByRole('button', { name: 'Load tournament', exact: true }).click();
    await expect(page.locator('.victory')).toHaveText('Champion: Ada');
  },
  { viewport: { width: 390, height: 844 } }, Scrollbars.hidden, TestTimeouts.long,
);

